-- Testdaten Wirtschaftlichkeit (Datenänderung, idempotent).
--
-- Die Seite Wirtschaftlichkeit rechnet aus erfassten Posten und Annahmen. Ohne Posten steht jede Kennzahl auf "offen",
-- und der Plan-Ist-Vergleich ist leer. Diese Migration erfasst die Investitionsrechnung der Geschäftsführung vom 23.09.2026
-- als Posten, so dass die Kennzahlen wieder auf die Vorgabe kommen:
--
--   Investition  154.000 EUR   (fünf Posten, Festpreis, belegt)
--   Betrieb       25.000 EUR   je Jahr (vier Posten, belegt)
--   Nutzen       200.000 EUR   je Jahr (vier Posten, geschätzt)
--   Amortisation 10,7 Monate, ROI im ersten Jahr 11,7 %, ROI über drei Jahre 162 %, TCO 229.000 EUR
--
-- Dazu drei Ist-Werte für den ersten Monat des Echtbetriebs (September 2026, in Tenge erfasst) und zwei festgehaltene Stände.
-- Die Standbilder sind mit baueSnapshot() aus lib/domain/wirtschaftlichkeit-erfassung.ts gerechnet, nicht von Hand geschrieben.
--
-- Schutz: Jede Tabelle wird nur gefüllt, wenn sie leer ist. Eigene Eingaben der Geschäftsführung werden nie ergänzt oder
-- verdoppelt. Eine leere Datenbank (CI, lokaler Stack vor dem Seed) bleibt leer, denn ohne Chargen gibt es keinen Betrieb.
-- Erkennbar sind die Zeilen an der Kennung 7e57da7a-0000-4000-8000-... (Testdaten).

update public.wirtschaftlichkeit_annahmen
   set vermarktete_menge_kg = 350000,
       echtbetrieb_beginn   = date '2026-09-01',
       herkunft             = herkunft || '{"menge": "geschaetzt"}'::jsonb
 where id = 1
   and vermarktete_menge_kg is null
   and echtbetrieb_beginn is null
   and exists (select 1 from public.chargen)
   and not exists (select 1 from public.wirtschaftlichkeit_posten);

