    ('7e57da7a-0000-4000-8000-000000000201', 'betrieb', 'Hosting', 'Hosting und Datenbank (Vercel, Supabase)', 7200, date '2026-09-01', 'belegt', null),
    ('7e57da7a-0000-4000-8000-000000000202', 'betrieb', 'Wartung', 'Wartung und Support mit vier Stunden Reaktionszeit', 9600, date '2026-09-01', 'belegt', null),
    ('7e57da7a-0000-4000-8000-000000000203', 'betrieb', 'Weiterentwicklung', 'Weiterentwicklung, kontingentiert auf 60 Stunden im Jahr', 5400, date '2026-09-01', 'belegt', null),
