    ('7e57da7a-0000-4000-8000-000000000301', 'nutzen', 'schwund', 'Geringerer Schwund vom Pflücken bis zum Kunden', 32000, date '2026-09-23', 'geschaetzt', 'Hochrechnung auf 350 t Jahresmenge: Verlustquote von 8,4 % (Baseline) auf 5,3 % (Chargen der Saison), bewertet mit 1.500 Tenge je kg. Das ergibt rund 31.700 EUR.'),
    ('7e57da7a-0000-4000-8000-000000000302', 'nutzen', 'handarbeit', 'Wegfall der Papier- und Excel-Erfassung (Steigen, Lohn, Berichte)', 88000, date '2026-09-23', 'geschaetzt', 'Geschätzt aus den Stunden für Erfassung, Lohnvorbereitung und Berichte der Betriebsleitung, der Buchhaltung und der Vorarbeiter im Vorjahr.'),
    ('7e57da7a-0000-4000-8000-000000000303', 'nutzen', 'audit', 'Auditvorbereitung: Rückverfolgbarkeit und Nachweise auf Knopfdruck', 46000, date '2026-09-23', 'geschaetzt', 'Geschätzt aus dem Aufwand für Nachweisordner und Rückfragen von Handelsketten vor der Saison.'),
