  ) as v(id, art, kategorie, bezeichnung, betrag, datum, herkunft, notiz)
 where exists (select 1 from public.chargen)
   and not exists (select 1 from public.wirtschaftlichkeit_posten)
on conflict (id) do nothing;

insert into public.wirtschaftlichkeit_ist (id, monat, kategorie, betrag, waehrung, notiz, erfasst_von_profil_id)
select v.id::uuid, v.monat, v.kategorie, v.betrag, v.waehrung, v.notiz, (select id from public.profiles where role::text = 'ceo' order by created_at limit 1)
  from (values
    ('7e57da7a-0000-4000-8000-000000000400', date '2026-09-01', 'schwund', 1150000, 'KZT', 'Erstmonat nach dem Start: Ausschuss laut Chargen, bewertet mit den Vollkosten.'),
    ('7e57da7a-0000-4000-8000-000000000401', date '2026-09-01', 'handarbeit', 2950000, 'KZT', 'Eingesparte Stunden bei Steigen-Erfassung und Lohnvorbereitung, von der Buchhaltung bestätigt.'),
    ('7e57da7a-0000-4000-8000-000000000402', date '2026-09-01', 'sonstiges', 640000, 'KZT', 'Eine Reklamation weniger als im Vormonat, zwei Abholfahrten gespart.')
  ) as v(id, monat, kategorie, betrag, waehrung, notiz)
 where exists (select 1 from public.chargen)
   and not exists (select 1 from public.wirtschaftlichkeit_ist)
on conflict (id) do nothing;

